  const [mat] = input;
  if (!Array.isArray(actual) || actual.length !== 2) return false;
  const [i, j] = actual;
  if (!Number.isInteger(i) || !Number.isInteger(j)) return false;
  if (i < 0 || i >= mat.length || j < 0 || j >= mat[0].length) return false;
  const at = (r, c) => (r >= 0 && r < mat.length && c >= 0 && c < mat[0].length ? mat[r][c] : -1);
  const value = mat[i][j];
  return value > at(i - 1, j) && value > at(i + 1, j) && value > at(i, j - 1) && value > at(i, j + 1);
}

