function validate([mat]) {
  if (!Array.isArray(mat) || mat.length < 1 || mat.length > 500) return 'mat needs 1 to 500 rows.';
  const cols = Array.isArray(mat[0]) ? mat[0].length : 0;
  if (cols < 1 || cols > 500) return 'Each row needs 1 to 500 values.';
  for (let i = 0; i < mat.length; i++) {
    if (!Array.isArray(mat[i]) || mat[i].length !== cols) return 'All rows must have the same length.';
    for (let j = 0; j < cols; j++) {
      const value = mat[i][j];
      if (!Number.isInteger(value) || value < 1 || value > 100000) return 'Each value is between 1 and 10^5.';
      if ((i > 0 && mat[i - 1][j] === value) || (j > 0 && mat[i][j - 1] === value)) return 'Cells that share a side must hold different values.';
    }
  }
  return null;
}

