function findPeakGrid(mat) {
  const maxColumn = (row) => {
    let best = 0;
    for (let j = 1; j < row.length; j++) {
      if (row[j] > row[best]) best = j;
    }
    return best;
  };

  let low = 0;
  let high = mat.length - 1;

  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    const col = maxColumn(mat[mid]);
    if (mat[mid][col] < mat[mid + 1][col]) {
      low = mid + 1;
    } else {
      high = mid;
    }
  }
  return [low, maxColumn(mat[low])];
}

