function findPeakGrid(mat) {
  const rows = mat.length;
  const cols = mat[0].length;
  const value = (r, c) => (r < 0 || r >= rows || c < 0 || c >= cols ? -1 : mat[r][c]);
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const here = mat[r][c];
      if (here > value(r - 1, c) && here > value(r + 1, c) && here > value(r, c - 1) && here > value(r, c + 1)) return [r, c];
    }
  }
  return [-1, -1];
}

