function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  let rows;
  let cols;
  let top;
  let shape = 0;
  if (size === 'large') {
    shape = pick(0, 3);
    rows = shape === 1 ? pick(1, 3) : pick(80, 100);
    cols = shape === 2 ? pick(1, 3) : pick(80, 100);
    top = pick(10, 100000);
  } else {
    rows = pick(1, 5);
    cols = pick(1, 5);
    top = pick(3, 12);
  }
  const mat = [];
  if (shape === 3) {
    // A smooth slope with its single peak in a random corner.
    const flipRows = rand() < 0.5;
    const flipCols = rand() < 0.5;
    for (let i = 0; i < rows; i++) {
      const r = flipRows ? rows - 1 - i : i;
      mat.push(Array.from({ length: cols }, (_, j) => 1 + r * cols + (flipCols ? cols - 1 - j : j)));
    }
    return [mat];
  }
  for (let i = 0; i < rows; i++) {
    const row = [];
    for (let j = 0; j < cols; j++) {
      let value = pick(1, top);
      while ((i > 0 && mat[i - 1][j] === value) || (j > 0 && row[j - 1] === value)) value = pick(1, top);
      row.push(value);
    }
    mat.push(row);
  }
  return [mat];
}
